use std::sync::mpsc;
use std::thread;

fn main() {
    let (tx, rx) = mpsc::channel();
    thread::spawn(move || {
        for n in 1..=3 {
            tx.send(n * 10).unwrap();
        }
    });   // tx moved into the thread; it is dropped when that thread finishes
    for value in rx {
        println!("got {value}");
    }
    println!("channel closed");
}

use std::sync::mpsc;
use std::thread;

// This does NOT compile: error[E0382]: borrow of moved value: `text`.
// send() took ownership of `text`, so we cannot print it afterwards.
fn broken() {
    let (tx, rx) = mpsc::channel();
    thread::spawn(move || {
        let text = String::from("hi");
        tx.send(text).unwrap();
        println!("{text}");
    });
    let _ = rx;
}

use std::sync::mpsc;
use std::thread;

fn main() {
    let (tx, rx) = mpsc::channel();
    for id in 1..=3 {
        let tx = tx.clone();   // each thread gets its own sender
        thread::spawn(move || {
            tx.send((id, id * id)).unwrap();
        });
    }
    drop(tx);   // the original sender must go too, or the loop below never ends

    let mut results = Vec::new();
    for message in rx {
        results.push(message);
    }
    results.sort();
    for (id, square) in results {
        println!("worker {id} sent {square}");
    }
}

